#!/usr/bin/env python3
from pathlib import Path
import hashlib,json,math
SRC=Path('market-navigator-turn28-ship.html');OUT=Path('market-navigator-turn29-pre-ship.html');PERSIST=Path('market-evidence/persistent-indices-v1.json');DERIVED=Path('market-evidence/derived-indices-persistent-v1.json');REG=Path('data/market-backend/component-registry-v1.json')
EXPECTED='544661884a412c57aac08fada4f961012a4bc496'; H=('1D','5D','MTD','YTD','1YR','3YR','5YR')
N={'risk':'RISK','growth':'GROWTH','macro':'MACRO'}
L={'qqq':'QQQ','copper':'Copper','smallCaps':'Small Caps','manufacturingProduction':'Manufacturing','wti':'WTI','unemployment':'Unemployment','payrolls':'Payrolls','vix':'VIX','move':'MOVE','hySpread':'HY Spread','hyg':'HYG','nfci':'NFCI','spy':'S&P 500','dxy':'Dollar','tenYear':'10Y Treasury','twoYear':'2Y Treasury','curve10y2y':'10Y–2Y Curve','curve10y3m':'10Y–3M Curve','cpi':'CPI','corePce':'Core PCE','fedFunds':'Fed Funds'}
def blob(b):return hashlib.sha1(f'blob {len(b)}\0'.encode()+b).hexdigest()
def one(s,a,b,n):
 if s.count(a)!=1:raise SystemExit(f'{n}: {s.count(a)} anchors')
 return s.replace(a,b,1)
def percentile(a,x):return sum(v<=x for v in a)/len(a) if a else .5
def cont(p):return 1+4*max(0,min(1,p))
def build():
 p=json.loads(PERSIST.read_text());d=json.loads(DERIVED.read_text());r=json.loads(REG.read_text());cm={x['id']:x for x in r['components']};o={'schema':'mn-dashboard-rollup-v2','forecast':False,'mechanics':'component continuous 1–5 favorability -> equal component mean index -> equal index mean environment','horizons':{}}
 for h in H:
  ix={}
  for k in ('risk','growth','macro'):
   q=p['indices'][k];n=max(1,len(d['indices'][k]['horizons'][h]['curve'])-1);e=len(q['values'])-1;b=max(0,e-n);sg=1 if k=='growth' else -1;cs=[]
   for sid in q['components']:
    x=q['componentSignals'][sid];cur=sg*(float(x[e])-float(x[b]));hist=[sg*(float(x[i])-float(x[i-n])) for i in range(n,len(x)) if x[i] is not None and x[i-n] is not None];sc=cont(percentile(hist,cur));cs.append({'id':sid,'label':L.get(sid,sid),'score':round(sc,4),'pct':round((sc-1)*25,2),'about':cm[sid].get('role','Governed Market Navigator component.')})
   raw=sum(x['score'] for x in cs)/len(cs);ix[k]={'label':N[k],'score':round(raw,4),'pct':round((raw-1)*25,2),'components':cs}
  env=sum(ix[k]['score'] for k in ix)/3;o['horizons'][h]={'environment':{'score':round(env,4),'pct':round((env-1)*25,2)},'indices':ix}
 return o
raw=SRC.read_bytes();assert blob(raw)==EXPECTED;s=raw.decode();D=build();dj=json.dumps(D,separators=(',',':'))
# rail: Dashboard is first class; NOW becomes CHART
s=one(s,'<nav><button class="nav on" data-view="now">NOW</button><button class="nav" data-view="library">LIBRARY</button><button class="nav" data-view="health">HEALTH</button></nav>','<nav><button class="nav on" data-view="dashboard">DASHBOARD</button><button class="nav" data-view="now">CHART</button><button class="nav" data-view="library">LIBRARY</button><button class="nav" data-view="health">HEALTH</button></nav>','rail')
# dashboard view before chart; chart no longer initial
view='''<section class="view on" id="view-dashboard"><div class="dash29"><div class="dash29Top"><div class="dash29Hz" id="dash29Hz"></div><div class="dash29MenuWrap"><button class="dash29More" id="dash29More" aria-label="Dashboard menu">…</button><div class="dash29Menu hidden" id="dash29Menu"><button data-dact="print">Print</button><button data-dact="json">Download data · JSON</button><button data-dact="csv">Download data · CSV</button></div></div></div><div class="dash29Scroll"><section class="dash29Env panel29" id="dash29Env"></section><div class="dash29Grid" id="dash29Grid"></div></div></div></section>'''
s=one(s,'<section class="view on" id="view-now">',view+'<section class="view" id="view-now">','dashboard view')
css='''
/* TURN29_DASHBOARD_V2 */
.dash29{height:100%;display:grid;grid-template-rows:44px minmax(0,1fr);padding:8px;gap:8px;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif}.dash29Top{display:flex;align-items:center;justify-content:center;position:relative}.dash29Hz{display:flex;gap:4px}.dash29Hz button{border:1px solid var(--line);background:var(--panel2);border-radius:7px;padding:6px 10px;font-size:11px;font-weight:750}.dash29Hz button.on{background:#17334d;border-color:#6e91ad}.dash29MenuWrap{position:absolute;right:0}.dash29More{width:34px;height:32px;border:1px solid var(--line);border-radius:7px;background:var(--panel2);font-size:18px}.dash29Menu{position:absolute;right:0;top:36px;width:190px;z-index:20;background:#081522;border:1px solid var(--line);border-radius:8px;overflow:hidden;box-shadow:0 14px 35px #0009}.dash29Menu button{width:100%;display:block;text-align:left;border:0;border-bottom:1px solid var(--line);background:transparent;padding:10px 12px}.dash29Scroll{min-height:0;overflow:auto}.panel29{background:var(--panel);border:1px solid var(--line);border-radius:9px;overflow:hidden}.dash29Env{padding:12px;margin-bottom:10px}.dash29Grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.dash29Col{min-width:0;background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:10px}.dash29Scale{display:grid;grid-template-columns:112px 1fr;gap:6px;margin-bottom:4px}.dash29Scale span:last-child{display:flex;justify-content:space-between;color:var(--muted);font-size:9px}.dash29Row{display:grid;grid-template-columns:112px minmax(0,1fr);gap:6px;align-items:center;min-height:32px}.dash29Row.index{min-height:38px;margin-bottom:8px}.dash29Label{height:26px;width:112px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;border:0;border-radius:4px;background:#07111b;color:#e8f1f8;text-align:left;padding:0 8px;font-size:12px;font-weight:650}.dash29Row.index .dash29Label,.dash29Env .dash29Label{font-weight:850}.dash29Track{height:26px;border:0;padding:0;display:flex;align-items:center;width:100%;cursor:pointer;background:#0c1b29}.dash29Row:nth-child(even) .dash29Track{background:#102131}.dash29Fill{display:block;height:13px;background:#8195a7;border-radius:1px;min-width:2px}.dash29Env .dash29Row{grid-template-columns:112px minmax(0,1fr)}.dash29Env .dash29Track{background:#0c1b29}.dash29Explain{position:absolute;z-index:50;inset:0;background:#02070dbb;display:grid;place-items:center;padding:12px}.dash29ExplainCard{position:relative;width:min(460px,94vw);background:#0b1928;border:1px solid var(--line);border-radius:9px;padding:16px 44px 16px 16px;font-size:13px;line-height:1.5}.dash29ExplainCard h3{margin:0 0 8px;font-size:15px}.dash29X{position:absolute;right:8px;top:8px;width:30px;height:30px;border:0;background:transparent;font-size:20px}@media(max-width:760px){.dash29{padding:6px}.dash29Grid{grid-template-columns:repeat(3,minmax(240px,1fr));overflow-x:auto}.dash29Scale,.dash29Row,.dash29Env .dash29Row{grid-template-columns:92px minmax(0,1fr)}.dash29Label{width:92px;font-size:11px}.dash29Col{padding:7px}}
@media print{.rail,.top,.dash29Top{display:none!important}.shell{display:block!important}.view{position:static!important;display:none!important}.view#view-dashboard{display:block!important}.dash29{padding:0}.dash29Scroll{overflow:visible}.dash29Grid{grid-template-columns:repeat(3,1fr)}}
'''
s=one(s,'</style></head>',css+'</style></head>','css')
# permit dashboard in routing and make it initial state
s=s.replace("if(!['now','library','health','config'].includes(v))v='now'","if(!['dashboard','now','library','health','config'].includes(v))v='dashboard'",1)
s=s.replace("$('shell').classList.toggle('nowMode',v==='now')","$('shell').classList.toggle('nowMode',v==='now'||v==='dashboard')",1)
s=s.replace("if(S.view==='now'){renderNowCrumb();return}","if(S.view==='now'){renderNowCrumb();return}if(S.view==='dashboard'){c.textContent='DASHBOARD';c.title='DASHBOARD';return}",1)
# runtime: label=explainer only, bar=chart only
js=f'''\nconst MN_DASH29={dj};let dash29H='5YR';
function dash29Download(name,type,text){{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{{type}}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{{URL.revokeObjectURL(a.href);a.remove()}},0)}}
function dash29Explain(title,text){{let m=document.createElement('div');m.className='dash29Explain';m.innerHTML=`<div class="dash29ExplainCard"><button class="dash29X" aria-label="Close">×</button><h3>${{esc(title)}}</h3><div>${{esc(text||'Governed Market Navigator measure.')}}</div></div>`;document.querySelector('.main').appendChild(m);m.querySelector('.dash29X').onclick=()=>m.remove()}}
function dash29Chart(k,c){{nav('now');S.h=dash29H;if(!k){{renderV1();return}};openV2(k);if(c)setTimeout(()=>{{S.componentsExpanded=true;renderV2();setTimeout(()=>{{let b=document.querySelector(`#legend [data-id="${{c}}"]`);if(b)b.click()}},60)}},40)}}
function dash29Row(label,pct,k,c,about,index=false){{return `<div class="dash29Row ${{index?'index':''}}"><button class="dash29Label" title="${{esc(label)}}">${{esc(label)}}</button><button class="dash29Track" aria-label="Open ${{esc(label)}} chart"><span class="dash29Fill" style="width:${{Math.max(0,Math.min(100,pct))}}%"></span></button></div>`}}
function dash29Wire(root,items){{root.querySelectorAll('.dash29Label').forEach((b,i)=>b.onclick=()=>dash29Explain(items[i].label,items[i].about));root.querySelectorAll('.dash29Track').forEach((b,i)=>b.onclick=()=>dash29Chart(items[i].k,items[i].c))}}
function renderDash29(){{let z=MN_DASH29.horizons[dash29H];$('dash29Hz').innerHTML={json.dumps(list(H))}.map(h=>`<button class="${{h===dash29H?'on':''}}" data-h="${{h}}">${{h}}</button>`).join('');$('dash29Hz').querySelectorAll('button').forEach(b=>b.onclick=()=>{{dash29H=b.dataset.h;renderDash29()}});let ei=[{{label:'ENVIRONMENT',about:'Equal mechanical rollup of the RISK, GROWTH and MACRO dashboard scores.',k:null,c:null}}];$('dash29Env').innerHTML=`<div class="dash29Scale"><span></span><span><b>0%</b><b>50%</b><b>100%</b></span></div>`+dash29Row('ENVIRONMENT',z.environment.pct,null,null,ei[0].about,true);dash29Wire($('dash29Env'),ei);let order=['risk','growth','macro'];$('dash29Grid').innerHTML=order.map(k=>{{let q=z.indices[k],items=[{{label:q.label,about:`${{q.label}} is the equal mechanical rollup of its seven displayed component favorability scores.`,k,c:null}},...q.components.map(c=>({{label:c.label,about:c.about,k,c:c.id}}))];return `<section class="dash29Col" data-k="${{k}}"><div class="dash29Scale"><span></span><span><b>0%</b><b>50%</b><b>100%</b></span></div>${{items.map((x,i)=>dash29Row(x.label,i?q.components[i-1].pct:q.pct,x.k,x.c,x.about,i===0)).join('')}}</section>`}}).join('');$('dash29Grid').querySelectorAll('.dash29Col').forEach((col,j)=>{{let k=order[j],q=z.indices[k],items=[{{label:q.label,about:`${{q.label}} is the equal mechanical rollup of its seven displayed component favorability scores.`,k,c:null}},...q.components.map(c=>({{label:c.label,about:c.about,k,c:c.id}}))];dash29Wire(col,items)}})}}
function dash29CSV(){{let z=MN_DASH29.horizons[dash29H],a=['horizon,level,index,id,label,score,percent'];a.push(`${{dash29H}},environment,,,,${{z.environment.score}},${{z.environment.pct}}`);for(let k of ['risk','growth','macro']){{let q=z.indices[k];a.push(`${{dash29H}},index,${{k}},,${{q.label}},${{q.score}},${{q.pct}}`);for(let c of q.components)a.push(`${{dash29H}},component,${{k}},${{c.id}},"${{c.label.replaceAll('"','""')}}",${{c.score}},${{c.pct}}`)}}return a.join('\\n')}}
setTimeout(()=>{{renderDash29();$('dash29More').onclick=()=>$('dash29Menu').classList.toggle('hidden');$('dash29Menu').onclick=e=>{{let a=e.target.dataset.dact;if(!a)return;$('dash29Menu').classList.add('hidden');if(a==='print')window.print();if(a==='json')dash29Download(`market-dashboard-${{dash29H}}.json`,'application/json',JSON.stringify(MN_DASH29.horizons[dash29H],null,2));if(a==='csv')dash29Download(`market-dashboard-${{dash29H}}.csv`,'text/csv',dash29CSV())}}}},0);\n'''
s=one(s,'mnxWireWhenReady();\nboot();',js+'\nmnxWireWhenReady();\nboot();','runtime')
# initial shell/crumb state follows dashboard visually
s=s.replace('<div class="crumb" id="crumb">ENVIRONMENT</div>','<div class="crumb" id="crumb">DASHBOARD</div>',1)
s=s.replace("view:'now'","view:'dashboard'",1)
s=one(s,'</body>','<div id="turn29BuildMarker" class="hidden" data-build="2026.09.30.turn29-dashboard-v2"></div></body>','marker')
OUT.write_text(s);Path('market-evidence/current-state-v1.json').write_text(json.dumps(D,indent=2)+'\n');print('PASS Turn29 dashboard v2',OUT.stat().st_size)
